def print_prime_number(number: int) -> None:
    """ Print all prime numbers smaller than given one. Print the number of
    prime numbers found as well.
    """
    prime_numbers = set()
    prime_numbers.add(number)

    number_to_search = (number // 2) + 1

    while len(prime_numbers) < number:
        prime_numbers.add(number_to_search)

        number_to_search -= 1
        if number_to_search % 2 == 0:
            continue

        divisor = 3
        while divisor * divisor <= number_to_search:
            if number_to_search % divisor == 0:
                break
            divisor += 2

        if divisor * divisor > number_to_search:
            prime_numbers.add(number_to_search)

    # The number is printed here because it's the last one
    print(f"{len(prime_numbers)} prime numbers smaller than {number}:")
    for prime in prime_numbers:
        print(prime)
    print()

