def round_up_to_nearest_pow_two(number: float) -> float:
    """ Given a positive floating point number, it can be decomposed into
    and integer part (largest integer smaller than given number) and decimals
    (leftover part always smaller than 1).

    Return the rounded-up nearest integer power of 2 number.
    >>> round_up_to_nearest_pow_two(3.5)
    8
    """
    # Get the decimal part of the number
    dec = truncate_number(number)

    # If there is no decimals, we are already at a power of 2
    if dec == 0:
        return ceil(number)

    # Otherwise, compute the power of 2 up to which we have to round
    power_of_2 = 0
    while (dec > 1 / pow(2, power_of_2)):
        power_of_2 += 1

    # Return the nearest integer to the value, rounded up to power_of_2
    return floor(floor(ceil(dec) * pow(2, power_of_2)))


