def find_nested_parens(paren_string: str) -> List[int]:
    if paren_string[0] == ')':
        return [1]
    if paren_string[-1] == '(':
        return [len(paren_string)]
    # parentheses can end after other parentheses in paren_string
    index_of_left_bracket = paren_string.index('(')
    left_bracket_level = 1 + find_nested_parens(paren_string[0:index_of_left_bracket])
    if index_of_left_bracket + len(paren_string[index_of_left_bracket + 1:]) == len(paren_string):
        right_bracket_level = 1
    else:
        right_bracket_level = 1 + find_nested_parens(paren_string[index_of_left_bracket + 1:])
    return left_bracket_level + right_bracket_level


