def get_groups(paren_string: str) -> List[str]:
    groups = []

    def recursion(i):
        # Base case:
        # If i index is after the last index,
        # return empty string.
        if i >= len(paren_string):
            return ''

        # if we're at the start of a parenthesis,
        # push it into the groups list
        # and recurse, starting from the next index
        if paren_string[i] == '(':
            groups.append(recursion(i + 1))
            return groups[-1]
        # if we're at a closing parenthesis,
        # push the strings that are contained in the group
        # and call the subfunction again
        # with the next character index as the starting point
        else:
            result = paren_string[i:].replace(')', '').replace('(', '')
            groups.append(result)
            return recursion(i + 1)

    return recursion(0)


